<template>
  <div
    id="app"
    :class="{
      'nav-dfm': largeTopAd,
      'home-topoguide': homePage,
      'no-top-ad': !topAd,
      'is-menu-pinned': sideMenuPinned || sideMenuKeptOpen,
    }"
  >
    <environment-banner />
    <side-menu :kept-open="sideMenuKeptOpen" class="side-menu no-print" />
    <navigation class="navigation no-print" :large-ad="largeTopAd" />
    <!-- the room under the navigation is left by this wrapper, not by the ad: ad blockers hide the elements named as
         ads (.ad, .ad-slot...), which then put the top of the page under the navigation -->
    <div v-if="topAd && !largeTopAd" class="top-bar-room">
      <dfm-ad-small />
    </div>
    <site-notice class="no-print site-notice" />
    <image-viewer v-if="imageViewerRequested" />
    <helper-window />
    <alert-window />

    <!-- the phone layout of the app (under PHONE_BREAKPOINT): a top bar and a bottom tab bar instead of the side menu and the navigation -->
    <mobile-top-bar v-if="appSettings.isMobileShell" />
    <mobile-menu v-if="appSettings.isMobileShell" />

    <!-- keep router view in last -->
    <div class="page-content is-block-print">
      <!-- without a network: what still opens -->
      <div v-if="!offline.online && !offlineBannerClosed" class="offline-banner no-print" role="status">
        <router-link :to="{ name: 'offline' }">
          <fa-icon icon="plug" />&nbsp;{{ $gettext('Offline: open Favourites') }}
        </router-link>
        <button
          type="button"
          class="delete is-small"
          :aria-label="$gettext('Close')"
          @click="offlineBannerClosed = true"
        />
      </div>
      <router-view class="router-view" />
    </div>
    <gdpr-banner></gdpr-banner>
    <device-favourites-prompt />
    <template v-if="appSettings.isMobileShell">
      <bottom-nav />
      <onboarding-tour />
      <pull-to-refresh />
    </template>
  </div>
</template>

<script setup lang="ts">
import { computed, defineAsyncComponent, onMounted, ref, watch } from 'vue';

import AlertWindow from './components/alert-window/AlertWindow.vue';
import BottomNav from './components/app/BottomNav.vue';
import DeviceFavouritesPrompt from './components/app/DeviceFavouritesPrompt.vue';
import MobileMenu from './components/app/MobileMenu.vue';
import MobileTopBar from './components/app/MobileTopBar.vue';
import OnboardingTour from './components/app/OnboardingTour.vue';
import PullToRefresh from './components/app/PullToRefresh.vue';
import GdprBanner from './components/gdpr/GdprBanner.vue';
import EnvironmentBanner from './components/generics/EnvironmentBanner.vue';
import HelperWindow from './components/helper/HelperWindow.vue';
import DfmAdSmall from './views/DfmAdSmall.vue';
import Navigation from './views/Navigation.vue';
import SideMenu from './views/SideMenu.vue';
import SiteNotice from './views/SiteNotice.vue';

import { useGlobalProperties } from '@/js/composables/global-properties';
import { useHasTopAd, useIsHomePage } from '@/js/composables/home-page';
import { useSideMenuCanPin, useSideMenuPinned } from '@/js/composables/side-menu';
import { imageViewerRequested } from '@/js/vue-plugins/image-viewer';
import { remind, shouldRemind } from '@/pwa/offline-reminder';
import { useAppSettingsStore } from '@/stores/app-settings';
import { useFavouritesStore } from '@/stores/favourites';
import { useOfflineStore } from '@/stores/offline';

// loaded with the first image shown, with Swiper (#4877)
const ImageViewer = defineAsyncComponent(() => import('./components/image-viewer/ImageViewer.vue'));

defineOptions({ name: 'App' });

const homePage = useIsHomePage();
const topAd = useHasTopAd();
const { $gettext, $router, $screen } = useGlobalProperties();
// in the navigation on wide screens (Navigation.vue), under it otherwise
const largeTopAd = computed(() => topAd.value && $screen.isWidescreen);
const sideMenuPinned = useSideMenuPinned();
const sideMenuCanPin = useSideMenuCanPin();
// the welcome page shows the menu open, without its pin, where the screen is wide enough
const sideMenuKeptOpen = computed(() => sideMenuCanPin.value && homePage.value);

const appSettings = useAppSettingsStore();

const offline = useOfflineStore();
// started at once: a logged in user's favourites of the device are sent to the account, the changes made without a
// network too
useFavouritesStore();
// closed until the network comes back and goes again
const offlineBannerClosed = ref(false);
watch(
  () => offline.online,
  (online) => {
    if (online) {
      offlineBannerClosed.value = false;
    }
  }
);

// once a day, online: the offline topos to download again (incomplete or old), before leaving
void offline.ready.then(() => {
  const count = offline.needingAttention.length;
  if (shouldRemind(count, offline.online)) {
    remind(`${$gettext('Offline topos to check:')} ${count}.`, $gettext('Favourites'), () => {
      void $router.push({ name: 'offline', query: { tab: 'offline' } });
    });
  }
});

onMounted(() => {
  document.getElementById('splashscreen')!.style.display = 'none';
});
</script>

